// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(address(this), address(this), address(this));
    }

    function testFuzz_property(
        address baseToken,
        address nft,
        uint128 virtualBaseTokenReserves,
        uint128 virtualNftReserves,
        uint56 changeFee,
        uint16 feeRate,
        bytes32 merkleRoot,
        bool useStolenNftOracle,
        bool payRoyalties
    ) public {
        // _baseToken must be nonzero so the rule is discriminating; nft must be nonzero so
        // initialize's effects are well-defined in both versions.
        vm.assume(baseToken != address(0));
        vm.assume(nft != address(0));
        vm.assume(feeRate <= 5_000); // admissible domain: otherwise both versions revert on fee rate

        c.initialize(
            baseToken,
            nft,
            virtualBaseTokenReserves,
            virtualNftReserves,
            changeFee,
            feeRate,
            merkleRoot,
            useStolenNftOracle,
            payRoyalties
        );

        // General rule: after a successful initialize(_baseToken, ...), the pool's base token
        // equals the _baseToken argument for EVERY admissible input.
        assertTrue(c.baseToken() == baseToken);
    }
}

